import 'package:flutter/material.dart';
import '../../core/database/app_database.dart';
class PurchasesPage extends StatefulWidget{const PurchasesPage({super.key});@override State<PurchasesPage> createState()=>_PurchasesPageState();}
class _PurchasesPageState extends State<PurchasesPage>{List<Map<String,Object?>> rows=const[];bool loading=true;
 Future<void> load()async{final db=await AppDatabase.instance.database;final x=await db.rawQuery('SELECT p.*,s.name supplier_name FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.created_at DESC');if(mounted)setState((){rows=x;loading=false;});}
 @override void initState(){super.initState();load();}
 Future<void> add()async{final db=await AppDatabase.instance.database;final ss=await db.query('suppliers',orderBy:'name'),ps=await db.query('products',orderBy:'name');if(ss.isEmpty||ps.isEmpty){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Add a supplier and product first.')));return;}String sid=ss.first['id'].toString(),pid=ps.first['id'].toString();final qty=TextEditingController(text:'1'),cost=TextEditingController(text:(ps.first['cost']??0).toString()),paid=TextEditingController(text:'0');final ok=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(title:const Text('New Purchase'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:sid,decoration:const InputDecoration(labelText:'Supplier'),items:ss.map((x)=>DropdownMenuItem(value:x['id'].toString(),child:Text(x['name'].toString()))).toList(),onChanged:(v)=>setLocal(()=>sid=v!)),const SizedBox(height:8),DropdownButtonFormField<String>(initialValue:pid,decoration:const InputDecoration(labelText:'Product'),items:ps.map((x)=>DropdownMenuItem(value:x['id'].toString(),child:Text(x['name'].toString()))).toList(),onChanged:(v)=>setLocal(()=>pid=v!)),const SizedBox(height:8),TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantity')),const SizedBox(height:8),TextField(controller:cost,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Cost price')),const SizedBox(height:8),TextField(controller:paid,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Paid'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))])));if(ok!=true)return;await AppDatabase.instance.createPurchase(id:DateTime.now().microsecondsSinceEpoch.toString(),supplierId:sid,items:[{'product_id':pid,'qty':double.tryParse(qty.text)??0,'cost':double.tryParse(cost.text)??0}],paid:double.tryParse(paid.text)??0);await load();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Purchases')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('New Purchase')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('No purchases yet.')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final x=rows[i];return ListTile(leading:const CircleAvatar(child:Icon(Icons.shopping_cart)),title:Text((x['supplier_name']??'Supplier').toString()),subtitle:Text(x['created_at'].toString()),trailing:Text('Total '+x['total'].toString()+'\nDue '+x['due'].toString(),textAlign:TextAlign.end));}));}
}